from math import comb

def zaslavsky(m: int, n: int) -> int:
    return sum(comb(m, k) for k in range(n + 1))

# Print Z(m,n) table
for m in range(10):
    row = [zaslavsky(m, n) for n in range(8)]
    print(f'm={m}: {row}')

# Verify Pascal recurrence
for m in range(15):
    for n in range(15):
        assert zaslavsky(m+1, n+1) == zaslavsky(m, n+1) + zaslavsky(m, n)
print('Pascal recurrence verified for all m,n < 15')

# Verify bounds
for m in range(21):
    for n in range(11):
        z = zaslavsky(m, n)
        assert z <= 2**m
        assert z <= (m+1)**n
        if m <= n:
            assert z == 2**m
print('All bounds verified')

from math import comb, log2

def zaslavsky(m: int, n: int) -> int:
    return sum(comb(m, k) for k in range(n + 1))

print('Depth Efficiency: Deep vs Shallow Networks')
print(f'{"w":>4} {"d":>4} {"L":>4} {"N":>5} {"log2(deep)":>12} {"log2(shallow_ub)":>18} {"gap":>8}')
for w, d, L in [(5,5,5), (10,10,5), (10,10,10), (8,10,8)]:
    N = w * L
    deep = zaslavsky(w, d) ** L
    shallow_ub = (N + 1) ** d
    print(f'{w:>4} {d:>4} {L:>4} {N:>5} {log2(deep):>12.1f} {log2(shallow_ub):>18.1f} {log2(deep)-log2(shallow_ub):>8.1f}')

from math import comb

def zaslavsky(m: int, n: int) -> int:
    return sum(comb(m, k) for k in range(n + 1))

def shatter_fn(m: int, n: int) -> int:
    if m == 0 or n == 0:
        return 1
    return shatter_fn(m-1, n) + shatter_fn(m-1, n-1)

count = 0
for m in range(13):
    for n in range(13):
        assert shatter_fn(m, n) == zaslavsky(m, n), f'Failed at m={m}, n={n}'
        count += 1
print(f'Sauer-Shelah identity verified for {count} pairs')

# Show what fraction of labelings are achievable
for n, d in [(10,2), (20,3), (50,5), (100,10)]:
    z = zaslavsky(n, d)
    print(f'n={n}, VC-dim≤{d}: {z:,} of {2**n:,} labelings ({z/2**n*100:.4f}%)')

